/** Life facts: synthetic-only tests (evidence level E2).
 *
 * Every fixture here is generated by this file into `os.tmpdir()`. Nothing reads
 * `data/`, a real runtime database, real activities or real memory, and nothing writes outside
 * that temporary directory.
 *
 * The suite pins the two failures the plan (§5 E 验收) names:
 *
 *   1. **把计划说成已完成** — an elapsed plan window must render as "the window ended", never as
 *      something that was done; `completed` requires execution evidence on the activity row.
 *   2. **无依据编造当前活动** — when no activity row is running, no rendering may claim "正在做".
 *
 * The last block counts both failures across the whole synthetic set and asserts zero.
 */
import { test, after } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {
  LIMITS, LIFE_STATES, RECORD_STATES, FRESHNESS_BANDS,
  collectLifeFacts, renderLifeFacts, resetLifeFactsCache,
  scopeSignature, isValidTimeZone, startOfLocalDay, localDateOf,
} from './life-facts.mjs';

// ── fixture: a synthetic runtime whose rows live in os.tmpdir() ────────────────

const FIXTURE_DIR = fs.mkdtempSync(path.join(os.tmpdir(), 'life-facts-fixture-'));
after(() => { try { fs.rmSync(FIXTURE_DIR, { recursive: true, force: true }); } catch { /* best effort */ } });

let fixtureCounter = 0;

/** World layout: rows keyed by a world name, so cross-scope reads are unambiguous. */
function writeWorldFixture(worlds) {
  fixtureCounter += 1;
  const file = path.join(FIXTURE_DIR, `world-${fixtureCounter}.json`);
  fs.writeFileSync(file, JSON.stringify(worlds), 'utf8');
  return file;
}

const BOUND_A = Object.freeze({ userId: 'owner', personaId: 'bot', worldId: 'world:a' });
const BOUND_B = Object.freeze({ userId: 'owner', personaId: 'bot', worldId: 'world:b' });

/**
 * Build a fake runtime from a JSON fixture file.
 *
 * Scope resolution mimics the real runtime's `resolveBinding`: an explicit binding wins, then
 * the session id, then the explicit scope key. The stub **reads its rows from disk** so the
 * fixture really lives in `os.tmpdir()` and no constant is smuggled in through a closure.
 */
function runtimeFromFixture(worlds, options = {}) {
  const file = writeWorldFixture(worlds);
  const load = () => JSON.parse(fs.readFileSync(file, 'utf8'));
  const readCounts = { p2Status: 0, listActivities: 0, listPlan: 0, todaySchedule: 0 };
  const resolveWorld = (input = {}) => {
    if (input.bound?.worldId) return input.bound.worldId;
    if (input.scopeKey) {
      const match = /w:([^|]+)/.exec(String(input.scopeKey));
      if (match) return match[1];
    }
    if (input.sessionId) return options.sessionWorlds?.[input.sessionId] ?? '';
    return '';
  };
  const world = (input) => {
    const data = load();
    return data[resolveWorld(input)] ?? null;
  };
  const guard = name => {
    if (options.throwOn?.includes(name)) throw Object.assign(new Error(`synthetic ${name} failure`), { code: 'db-open-failed' });
    if (options.missing?.includes(name)) return undefined;
  };
  return {
    readCounts,
    p2Status(input = {}) {
      readCounts.p2Status += 1;
      guard('p2Status');
      const rows = world(input) ?? {};
      return {
        planning: { enabled: rows.planningEnabled !== false, paused: false, state: rows.planningState ?? 'idle' },
        activities: { enabled: rows.activitiesEnabled !== false, paused: false, state: 'idle', running: (rows.activities ?? []).filter(row => row.status === 'running').length },
        budget: null,
      };
    },
    listActivities(input = {}) {
      readCounts.listActivities += 1;
      guard('listActivities');
      const rows = world(input);
      if (!rows) return { ok: false, code: rows === null && resolveWorld(input) === '' ? 'unbound' : 'unbound' };
      return { ok: true, activities: rows.activities ?? [] };
    },
    listPlan(input = {}) {
      readCounts.listPlan += 1;
      guard('listPlan');
      const rows = world(input);
      if (!rows) return { ok: false, code: 'unbound' };
      return { ok: true, plan: rows.plan ?? null, slots: rows.slots ?? [] };
    },
    todaySchedule(input = {}) {
      readCounts.todaySchedule += 1;
      guard('todaySchedule');
      const rows = world(input);
      if (!rows) return { ok: false, code: 'unbound' };
      if (rows.agendaEnabled === false) return { ok: true, enabled: false, state: 'disabled', items: [], occurrences: [] };
      return { ok: true, enabled: true, state: 'active', items: rows.items ?? [], occurrences: rows.occurrences ?? [] };
    },
  };
}

// Convenient instants, all in Asia/Shanghai (UTC+8). Tests always inject `now`.
const AT = (iso) => new Date(iso).getTime();
const NOW_AFTERNOON = AT('2026-11-14T15:00:00+08:00');

function panicked(runtime) {
  return {
    p2Status: runtime.p2Status,
    listActivities: runtime.listActivities,
    listPlan: runtime.listPlan,
    todaySchedule: runtime.todaySchedule,
  };
}

// ── 1. 正在看视频 ─────────────────────────────────────────────────────────────

test('正在看视频：running 活动是执行事实，进度来自行的证据字段', () => {
  resetLifeFactsCache();
  const runtime = runtimeFromFixture({
    'world:a': {
      activities: [{
        activityId: 'act-video', kind: 'watch', adapter: 'bilibili', reality: 'actual_tool_activity',
        status: 'running', target: '看合成样本视频', consumed: 12, totalUnits: 30,
        startedAt: NOW_AFTERNOON - 20 * 60_000, updatedAt: NOW_AFTERNOON - 60_000,
      }],
      slots: [],
    },
  });
  const facts = collectLifeFacts({ runtime, bound: BOUND_A, timeZone: 'Asia/Shanghai', now: NOW_AFTERNOON, cacheTtlMs: 60_000 });

  assert.equal(facts.state, 'running');
  assert.equal(facts.ok, true);
  assert.equal(facts.activities.current.id, 'act-video');
  assert.equal(facts.activities.current.source, 'p2-activity');
  assert.equal(facts.activities.current.sourceRank, 1);
  assert.equal(facts.activities.current.status, 'running');
  assert.equal(facts.activities.current.state, 'running');
  assert.equal(facts.activities.current.scope, scopeSignature(BOUND_A));
  assert.equal(facts.activities.current.observedAt, NOW_AFTERNOON - 60_000);
  assert.equal(facts.activities.current.evidence.kind, 'consumed');
  assert.equal(facts.activities.current.evidence.consumed, 12);
  assert.equal(facts.activities.current.freshness, 'live');
  assert.equal(facts.activities.current.receiptRef, 'activity:act-video');
  assert.equal(facts.activities.current.receiptSource, 'activity-evidence');

  const rendered = renderLifeFacts(facts);
  assert.match(rendered, /正在做：watch · 看合成样本视频/);
  assert.match(rendered, /进度 12\/30/);
  assert.doesNotMatch(rendered, /已完成|已经做完|做完了/);
});

// ── 2. 暂停阅读 ───────────────────────────────────────────────────────────────

test('暂停阅读：paused 是当前活动但不是完成，渲染必须写明没有完成证据', () => {
  resetLifeFactsCache();
  const runtime = runtimeFromFixture({
    'world:a': {
      activities: [{
        activityId: 'act-read', kind: 'read', reality: 'actual_tool_activity', status: 'paused',
        target: '读合成样本第三章', consumed: 4, totalUnits: 9,
        startedAt: NOW_AFTERNOON - 40 * 60_000, updatedAt: NOW_AFTERNOON - 5 * 60_000,
      }],
    },
  });
  const facts = collectLifeFacts({ runtime, bound: BOUND_A, now: NOW_AFTERNOON });

  assert.equal(facts.state, 'paused');
  assert.equal(facts.activities.paused.id, 'act-read');
  assert.equal(facts.activities.paused.state, 'paused');
  assert.equal(facts.activities.current, null, 'paused 不能冒充 running');
  assert.equal(facts.activities.counts.completedEvidenced, 0);
  assert.equal(facts.activities.recentCompleted.length, 0);

  const rendered = renderLifeFacts(facts);
  assert.match(rendered, /暂停中：读合成样本第三章/);
  assert.match(rendered, /没有完成证据/);
  assert.doesNotMatch(rendered, /正在做/);
});

// ── 3. 计划写作但未开始 ───────────────────────────────────────────────────────

test('计划写作但未开始：只有计划槽 ⇒ scheduled，渲染明说“计划，不是已经做了”', () => {
  resetLifeFactsCache();
  const runtime = runtimeFromFixture({
    'world:a': {
      activities: [],
      plan: { planId: 'plan-1', day: '2026-11-14', version: 3, status: 'committed', summary: '合成日程' },
      slots: [{
        slotId: 'slot-write', startAt: AT('2026-11-14T20:00:00+08:00'), endAt: AT('2026-11-14T21:00:00+08:00'),
        kind: 'activity', activity: 'write', title: '写一段合成日记', status: 'planned', flexibility: 'soft', targetRef: '',
      }],
    },
  });
  const facts = collectLifeFacts({ runtime, bound: BOUND_A, now: NOW_AFTERNOON });

  assert.equal(facts.state, 'scheduled');
  assert.equal(facts.plan.available, true);
  assert.equal(facts.plan.next.id, 'slot-write');
  assert.equal(facts.plan.next.state, 'scheduled');
  assert.equal(facts.plan.next.lifecycleReason, 'planned-for-later');
  assert.equal(facts.plan.next.source, 'p2-plan');
  assert.equal(facts.plan.next.sourceRank, 2);
  assert.equal(facts.plan.next.receiptRef, '');
  assert.equal(facts.plan.next.receiptSource, 'none');
  assert.equal(facts.counters.completedEvidenced, 0);

  const rendered = renderLifeFacts(facts);
  assert.match(rendered, /接下来（20:00–21:00）：写一段合成日记/);
  assert.match(rendered, /计划，不是已经做了/);
  assert.doesNotMatch(rendered, /正在做|已完成|已经做完/);
});

// ── 4. 当天无安排 ─────────────────────────────────────────────────────────────

test('当天无安排：真空闲报 idle，并说明“此刻没有在做”而不是“做过什么”', () => {
  resetLifeFactsCache();
  const runtime = runtimeFromFixture({ 'world:a': { activities: [], plan: null, slots: [], agendaEnabled: true, occurrences: [], items: [] } });
  const facts = collectLifeFacts({ runtime, bound: BOUND_A, now: NOW_AFTERNOON });

  assert.equal(facts.state, 'idle');
  assert.equal(facts.ok, true);
  assert.equal(facts.activities.counts.read, 0);
  assert.equal(facts.plan.slots.length, 0);
  assert.equal(facts.schedule.today.length, 0);
  assert.deepEqual(facts.conflicts, []);

  const rendered = renderLifeFacts(facts);
  assert.match(rendered, /当前没有正在执行的活动，也没有到点的计划或日程/);
  assert.doesNotMatch(rendered, /正在做|暂停中|已完成/);
});

// ── 5. 模块关闭 ───────────────────────────────────────────────────────────────

test('模块关闭：报 disabled 且不假装空闲，也不去读任何活动', () => {
  resetLifeFactsCache();
  const runtime = runtimeFromFixture({ 'world:a': { activitiesEnabled: false, planningEnabled: false, activities: [], slots: [] } });
  const facts = collectLifeFacts({ runtime, bound: BOUND_A, now: NOW_AFTERNOON });

  assert.equal(facts.state, 'disabled');
  assert.notEqual(facts.state, 'idle');
  assert.equal(facts.ok, false);
  assert.equal(runtime.readCounts.listActivities, 0, '关闭时不该读活动表');
  assert.match(facts.reasons.join(' '), /activities-disabled/);
  assert.match(facts.reasons.join(' '), /planning-disabled/);

  const rendered = renderLifeFacts(facts);
  assert.match(rendered, /自主规划与活动当前未启用/);
  assert.match(rendered, /不是“没有安排”/);
  assert.doesNotMatch(rendered, /idle|空闲/);
});

// ── 6. 数据库读失败（throw） ─────────────────────────────────────────────────

test('数据库读失败：抛出的异常变成 read-failed，不冒泡给调用方', () => {
  resetLifeFactsCache();
  const runtime = runtimeFromFixture({ 'world:a': { activities: [], slots: [] } }, { throwOn: ['listActivities', 'listPlan', 'todaySchedule'] });
  let facts;
  assert.doesNotThrow(() => { facts = collectLifeFacts({ runtime, bound: BOUND_A, now: NOW_AFTERNOON }); });

  assert.equal(facts.state, 'read-failed');
  assert.equal(facts.ok, false);
  assert.ok(facts.failures.length >= 3);
  assert.equal(facts.failures[0].code, 'db-open-failed');
  assert.match(facts.reasons.join(' '), /p2Activity-db-open-failed/);

  const rendered = renderLifeFacts(facts);
  assert.match(rendered, /生活状态读取失败/);
  assert.match(rendered, /读不到不等于空闲/);
  assert.doesNotMatch(rendered, /正在做|暂停中/);
  assert.doesNotMatch(rendered, /当前没有正在执行的活动/);
});

