// ── 10. 过期计划不得渲染成已完成 ──────────────────────────────────────────────

test('过期计划：窗口结束只能说 window-ended，绝不能渲染成已完成', () => {
  resetLifeFactsCache();
  const runtime = runtimeFromFixture({
    'world:a': {
      activities: [],
      plan: { planId: 'plan-1', day: '2026-11-14', version: 1, status: 'committed', summary: '' },
      slots: [
        { slotId: 'slot-morning', startAt: AT('2026-11-14T09:00:00+08:00'), endAt: AT('2026-11-14T10:00:00+08:00'), kind: 'activity', activity: 'write', title: '上午写合成短文', status: 'planned' },
        { slotId: 'slot-noon', startAt: AT('2026-11-14T13:00:00+08:00'), endAt: AT('2026-11-14T14:00:00+08:00'), kind: 'activity', activity: 'read', title: '午后读合成章节', status: 'done' },
      ],
    },
  });
  const facts = collectLifeFacts({ runtime, bound: BOUND_A, now: NOW_AFTERNOON });

  for (const slot of facts.plan.slots) {
    assert.equal(slot.state, 'window-ended', `${slot.id} 过期不得变成 completed`);
    assert.equal(slot.receiptRef, '');
    assert.equal(slot.receiptSource, 'none');
  }
  assert.equal(facts.plan.slots.find(slot => slot.id === 'slot-morning').lifecycleReason, 'window-ended-without-activity');
  assert.equal(
    facts.plan.slots.find(slot => slot.id === 'slot-noon').lifecycleReason,
    'slot-done-without-activity-evidence',
    'status=done 但没有活动证据，同样只能算窗口结束',
  );
  assert.equal(facts.counters.completedEvidenced, 0);
  assert.equal(facts.counters.windowEnded, 2);
  assert.equal(facts.plan.endedToday.length, 2);

  const rendered = renderLifeFacts(facts);
  assert.match(rendered, /计划窗口已结束、但没有执行证据：上午写合成短文（09:00–10:00）/);
  assert.match(rendered, /只能说这个时间段过去了，不能说做过/);
  assert.match(rendered, /计划窗口已结束、但没有执行证据：午后读合成章节/);
  assert.doesNotMatch(rendered, /已完成|已经做|做完了|刚看完/);
});

test('有执行证据的 done 才算 completed；status=done 但没有证据的不进最近完成', () => {
  resetLifeFactsCache();
  const runtime = runtimeFromFixture({
    'world:a': {
      plan: { planId: 'plan-1', day: '2026-11-14', version: 1, status: 'committed', summary: '' },
      activities: [
        {
          activityId: 'act-done-evidenced', kind: 'read', reality: 'actual_tool_activity', status: 'done',
          target: '读完合成章节', consumed: 8, totalUnits: 8, artifactRef: 'artifact/synthetic.md', artifactVersion: 2,
          startedAt: AT('2026-11-14T13:30:00+08:00'), updatedAt: AT('2026-11-14T14:00:00+08:00'),
        },
        {
          activityId: 'act-done-empty', kind: 'write', reality: 'actual_tool_activity', status: 'done',
          target: '没写出来的合成段落', consumed: 0, totalUnits: 0, artifactRef: '', artifactVersion: 0,
          startedAt: AT('2026-11-14T10:00:00+08:00'), updatedAt: AT('2026-11-14T10:30:00+08:00'),
        },
      ],
      slots: [
        { slotId: 'slot-read', startAt: AT('2026-11-14T13:30:00+08:00'), endAt: AT('2026-11-14T14:00:00+08:00'), kind: 'activity', activity: 'read', title: '读完合成章节', status: 'done' },
        { slotId: 'slot-write', startAt: AT('2026-11-14T10:00:00+08:00'), endAt: AT('2026-11-14T10:30:00+08:00'), kind: 'activity', activity: 'write', title: '没写出来的合成段落', status: 'done' },
      ],
    },
  });
  const facts = collectLifeFacts({ runtime, bound: BOUND_A, now: NOW_AFTERNOON });

  // The unevidenced `done` row must stay visible as a record — but only as "no evidence".
  const unevidenced = facts.activities.others.find(record => record.id === 'act-done-empty');
  assert.ok(unevidenced, `others=${facts.activities.others.map(record => record.id).join(',')}`);
  assert.equal(unevidenced.state, 'unknown');
  assert.equal(unevidenced.lifecycleReason, 'done-without-evidence');
  assert.equal(unevidenced.receiptRef, '');
  const completed = facts.activities.recentCompleted;
  assert.equal(completed.length, 1, '只有带证据的那条进入最近完成');
  assert.equal(completed[0].id, 'act-done-evidenced');
  assert.equal(completed[0].state, 'completed');
  assert.equal(completed[0].receiptRef, 'activity:act-done-evidenced');
  assert.equal(facts.counters.completedEvidenced, 1);
  assert.equal(facts.counters.completedUnevidenced, 1);

  const slotRead = facts.plan.slots.find(slot => slot.id === 'slot-read');
  assert.equal(slotRead.state, 'completed');
  assert.equal(slotRead.lifecycleReason, 'slot-done-with-matching-activity-evidence');

  const rendered = renderLifeFacts(facts);
  assert.match(rendered, /有执行证据的完成：读完合成章节（activity:act-done-evidenced）/);
  assert.doesNotMatch(rendered, /没写出来的合成段落.*已完成/);
});

// ── 来源冲突如实显示 ─────────────────────────────────────────────────────────

test('来源冲突：正在看的与计划里的不是同一件事时，两边都如实显示', () => {
  resetLifeFactsCache();
  const runtime = runtimeFromFixture({
    'world:a': {
      activities: [{
        activityId: 'act-watch', kind: 'watch', status: 'running', target: '看合成视频',
        consumed: 5, totalUnits: 20, startedAt: NOW_AFTERNOON - 600_000, updatedAt: NOW_AFTERNOON - 30_000,
      }],
      plan: { planId: 'plan-1', day: '2026-11-14', version: 1, status: 'committed', summary: '' },
      slots: [{
        slotId: 'slot-write', startAt: NOW_AFTERNOON - 10 * 60_000, endAt: NOW_AFTERNOON + 50 * 60_000,
        kind: 'activity', activity: 'write', title: '写合成日记', status: 'planned',
      }],
    },
  });
  const facts = collectLifeFacts({ runtime, bound: BOUND_A, now: NOW_AFTERNOON });

  assert.equal(facts.state, 'running');
  const conflict = facts.conflicts.find(item => item.code === 'activity-plan-mismatch');
  assert.ok(conflict, JSON.stringify(facts.conflicts));
  assert.equal(conflict.a.summary, '看合成视频');
  assert.equal(conflict.b.summary, '写合成日记');
  assert.deepEqual(conflict.sources, ['p2-activity', 'p2-plan']);

  const rendered = renderLifeFacts(facts);
  assert.match(rendered, /来源冲突（activity-plan-mismatch）：p2-activity 说 看合成视频；p2-plan 说 写合成日记/);
  assert.match(rendered, /不要择一掩盖/);
  // Both sources survive: the running activity and the planned slot are both reported.
  assert.match(rendered, /正在做：watch · 看合成视频/);
  assert.match(rendered, /计划里现在这一段：写合成日记/);
});

