// ── freshness 分带 ───────────────────────────────────────────────────────────

test('freshness：live / aging / stale / unknown 四带与 TTL 关系明确', () => {
  resetLifeFactsCache();
  const ttl = 60_000;
  const old = NOW_AFTERNOON - 20 * ttl;   // 20×TTL → stale
  const runtime = runtimeFromFixture({
    'world:a': {
      activities: [
        { activityId: 'act-old', kind: 'read', status: 'done', target: '很久之前的合成阅读', consumed: 3, totalUnits: 3, startedAt: old, updatedAt: old },
        { activityId: 'act-no-time', kind: 'read', status: 'done', target: '没有时间戳的合成阅读', consumed: 2, totalUnits: 2, startedAt: 0, updatedAt: 0 },
      ],
      slots: [],
    },
  });
  const facts = collectLifeFacts({
    runtime,
    bound: BOUND_A,
    now: NOW_AFTERNOON,
    // Force a re-read so the cached snapshot is not reused between sub-assertions.
    force: true,
  });
  const records = facts.activities.recentCompleted;
  assert.equal(records.find(record => record.id === 'act-old').freshness, 'stale');
  assert.equal(records.find(record => record.id === 'act-old').freshnessAgeMs, 20 * ttl);
  assert.equal(records.find(record => record.id === 'act-no-time').freshness, 'unknown');
  assert.deepEqual([...FRESHNESS_BANDS], ['live', 'aging', 'stale', 'unknown']);

  const rendered = renderLifeFacts(facts);
  assert.match(rendered, /这是上一次的记录，不是现在/);
  assert.match(rendered, /时间未知/);
});

