test('词表：顶层状态只允许八个词，记录状态与合同原生 status 各自保留', () => {
  assert.deepEqual([...LIFE_STATES], ['disabled', 'idle', 'scheduled', 'running', 'paused', 'completed', 'unknown', 'read-failed']);
  assert.ok(RECORD_STATES.includes('window-ended'), 'window-ended 是记录级新增词，不与顶层状态冲突');
  assert.ok(!LIFE_STATES.includes('window-ended'), 'window-ended 不得冒充顶层状态');
  resetLifeFactsCache();
  const runtime = runtimeFromFixture({ 'world:a': { activities: [], slots: [] } });
  const facts = collectLifeFacts({ runtime, bound: BOUND_A, now: NOW_AFTERNOON });
  assert.ok(LIFE_STATES.includes(facts.state), `state=${facts.state}`);
  for (const slot of facts.plan.slots) assert.ok(RECORD_STATES.includes(slot.state), `slot state=${slot.state}`);
});

test('渲染有界：条数与字符都不超过声明上限，且空/坏输入返回空串', () => {
  assert.equal(renderLifeFacts(null), '');
  assert.equal(renderLifeFacts({}), '');
  assert.equal(renderLifeFacts('text'), '');

  resetLifeFactsCache();
  const runtime = runtimeFromFixture({
    'world:a': {
      activities: Array.from({ length: 6 }, (_, index) => ({
        activityId: `act-done-${index}`, kind: 'read', status: 'done', target: `合成完成 ${index}`,
        consumed: 1, totalUnits: 1, startedAt: NOW_AFTERNOON - 3600_000, updatedAt: NOW_AFTERNOON - 60_000,
      })),
      plan: { planId: 'plan-1', day: '2026-11-14', version: 1, status: 'committed', summary: '' },
      slots: Array.from({ length: 18 }, (_, index) => ({
        slotId: `slot-old-${index}`, startAt: NOW_AFTERNOON - (index + 1) * 3600_000, endAt: NOW_AFTERNOON - (index + 1) * 3600_000 + 1_800_000,
        kind: 'activity', activity: 'read', title: `早已过期的计划 ${index}`, status: 'planned',
      })),
    },
  });
  const facts = collectLifeFacts({ runtime, bound: BOUND_A, now: NOW_AFTERNOON });
  const rendered = renderLifeFacts(facts);
  const lines = rendered.split('\n');
  assert.ok(lines.length <= LIMITS.maxRenderLines + 1, `lines=${lines.length}`);
  assert.ok(rendered.length <= LIMITS.maxRenderChars + 60, `chars=${rendered.length}`);
  assert.ok(facts.counters.records <= LIMITS.maxRecords);
  assert.ok(rendered.startsWith('【今天的生活·事实快照】'));
});

test('纯只读：同一进程重复调用不改变 fixture 文件内容，也不创建新文件', () => {
  resetLifeFactsCache();
  const runtime = runtimeFromFixture({ 'world:a': { activities: [], slots: [] } });
  const before = fs.readdirSync(FIXTURE_DIR).sort();
  const fileBefore = fs.readFileSync(path.join(FIXTURE_DIR, before.at(-1)), 'utf8');
  collectLifeFacts({ runtime, bound: BOUND_A, now: NOW_AFTERNOON, force: true });
  collectLifeFacts({ runtime, bound: A2(), now: NOW_AFTERNOON + 1000, force: true });
  const after = fs.readdirSync(FIXTURE_DIR).sort();
  assert.deepEqual(after, before, '模块不得新增文件');
  assert.equal(fs.readFileSync(path.join(FIXTURE_DIR, before.at(-1)), 'utf8'), fileBefore, '模块不得改写 fixture');
});

function A2() {
  return { userId: 'owner-2', personaId: 'bot', worldId: 'world:a' };
}

// ── 验收：两类失败在合成集里的命中计数必须为 0 ───────────────────────────────

test('合成集统计：把计划说成已完成 0 条，无依据编造当前活动 0 条', () => {
  resetLifeFactsCache();
  const scenarios = [];
  const add = (name, worlds, options = {}) => {
    const runtime = runtimeFromFixture(worlds, options);
    const input = { runtime, bound: BOUND_A, now: NOW_AFTERNOON, force: true, ...(options.input ?? {}) };
    const facts = collectLifeFacts(input);
    scenarios.push({ name, facts, rendered: renderLifeFacts(facts) });
  };

  add('running-watch', { 'world:a': { activities: [{ activityId: 'a1', kind: 'watch', status: 'running', target: '看合成视频', consumed: 3, totalUnits: 9, startedAt: NOW_AFTERNOON - 60_000, updatedAt: NOW_AFTERNOON }] } });
  add('paused-read', { 'world:a': { activities: [{ activityId: 'a2', kind: 'read', status: 'paused', target: '读合成章节', consumed: 2, totalUnits: 5, startedAt: NOW_AFTERNOON - 60_000, updatedAt: NOW_AFTERNOON }] } });
  add('planned-write', { 'world:a': { activities: [], slots: [{ slotId: 's1', startAt: NOW_AFTERNOON + 3600_000, endAt: NOW_AFTERNOON + 7200_000, kind: 'activity', activity: 'write', title: '写合成日记', status: 'planned' }] } });
  add('expired-planned', { 'world:a': { activities: [], slots: [{ slotId: 's2', startAt: NOW_AFTERNOON - 7200_000, endAt: NOW_AFTERNOON - 3600_000, kind: 'activity', activity: 'write', title: '上午的合成计划', status: 'planned' }] } });
  add('expired-done-unevidenced', { 'world:a': { activities: [], slots: [{ slotId: 's3', startAt: NOW_AFTERNOON - 7200_000, endAt: NOW_AFTERNOON - 3600_000, kind: 'activity', activity: 'read', title: '号称做完的合成计划', status: 'done' }] } });
  add('empty-day', { 'world:a': { activities: [], slots: [] } });
  add('disabled', { 'world:a': { activitiesEnabled: false, planningEnabled: false, activities: [], slots: [] } });
  add('read-throw', { 'world:a': { activities: [], slots: [] } }, { throwOn: ['listActivities', 'listPlan', 'todaySchedule'] });
  add('unbound', { 'world:a': { activities: [], slots: [] } }, { input: { bound: null, sessionId: '', scopeKey: '' } });
  add('cross-session', {
    'world:a': { activities: [], slots: [] },
    'world:b': { activities: [{ activityId: 'a3', kind: 'write', status: 'running', target: 'B 世界在写', consumed: 1, totalUnits: 2, startedAt: NOW_AFTERNOON - 60_000, updatedAt: NOW_AFTERNOON }] },
  }, { sessionWorlds: { 'sess-b': 'world:b' }, input: { sessionId: 'sess-b' } });

  // Claim 1: no rendering may assert a plan slot was performed.
  const performedClaims = /\b已完成\b|已经做完|已经做过了|刚看完|做完了|看完了/;
  const claimHits = scenarios
    .filter(scenario => performedClaims.test(scenario.rendered))
    .map(scenario => scenario.name);
  assert.deepEqual(claimHits, [], `把计划说成已完成的命中：${claimHits.join(',')}`);

  // Claim 2: no rendering may assert a running activity when no row is running.
  const runningClaim = /正在做：/;
  const invented = scenarios
    .filter(scenario => !scenario.facts.activities.current)
    .filter(scenario => runningClaim.test(scenario.rendered))
    .map(scenario => scenario.name);
  assert.deepEqual(invented, [], `无依据编造当前活动的命中：${invented.join(',')}`);

  // Sanity: the set really exercised both sides, so a zero above is not vacuous.
  const withRunning = scenarios.filter(scenario => runningClaim.test(scenario.rendered)).map(scenario => scenario.name);
  const withWindowEnded = scenarios.filter(scenario => /计划窗口已结束/.test(scenario.rendered)).map(scenario => scenario.name);
  assert.deepEqual(withRunning, ['running-watch'], '有 running 行的场景必须真的渲染“正在做”');
  assert.ok(withWindowEnded.length >= 2, `window-ended 覆盖不足：${withWindowEnded.join(',')}`);
});
